import{_ as a,o as e,c as n,a5 as l}from"./chunks/framework.DfywBLEo.js";const u=JSON.parse('{"title":"资源托管","description":"","frontmatter":{},"headers":[],"relativePath":"guide/resourceCdn.md","filePath":"guide/resourceCdn.md","lastUpdated":1792557099000}'),p={name:"guide/resourceCdn.md"};function o(r,s,t,c,i,d){return e(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="资源托管" tabindex="-1">资源托管 <a class="header-anchor" href="#资源托管" aria-label="Permalink to &quot;资源托管&quot;">​</a></h1><p>可以将插件放到自己的静态资源服务上，通过 HTTPS 加载。</p><h2 id="上传资源" tabindex="-1">上传资源 <a class="header-anchor" href="#上传资源" aria-label="Permalink to &quot;上传资源&quot;">​</a></h2><p>上传编译后的整个 <code>dist/</code> 目录，保留目录结构。插件会继续加载其中的脚本分包、CSS、字体和图片，只有 <code>simpleMemory.js</code> 不能正常运行。</p><p>例如上传到网站的 <code>/simplememory/v2.1.7/</code> 目录后：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span>
<span class="line"><span style="color:#EEE6F7;">window.</span><span style="color:#F0ADC4;">cnblogsConfig</span><span style="color:#F0ADC4;"> =</span><span style="color:#EEE6F7;"> {</span></span>
<span class="line"><span style="color:#B8ABC9;">  // 填写自己的配置</span></span>
<span class="line"><span style="color:#EEE6F7;">};</span></span>
<span class="line"><span style="color:#EEE6F7;">&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span>
<span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#F0ADC4;"> src</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;https://example.com/simplememory/v2.1.7/simpleMemory.js&quot;</span><span style="color:#F0ADC4;"> defer</span><span style="color:#EEE6F7;">&gt;&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>后台「页面定制 CSS」仍需填写同一版本的 <code>simpleMemory.css</code> 内容。跨域提供字体时，还需要资源服务允许相应的跨域请求。</p><h2 id="检查加载" tabindex="-1">检查加载 <a class="header-anchor" href="#检查加载" aria-label="Permalink to &quot;检查加载&quot;">​</a></h2><p>在博客页面打开浏览器开发者工具，检查 Network 面板：</p><ul><li>入口脚本及后续资源没有 404、403 或证书错误。</li><li>JavaScript、CSS 和字体请求返回对应文件，不能是网站的 HTML 错误页。</li><li>资源地址可以公开访问，不需要登录。</li></ul><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>建议每个版本使用独立目录。更新时上传完整资源、替换后台 CSS，再修改脚本地址。不要立即删除旧版本文件，详见<a href="./versionSwitch.html">版本切换</a>。</p>`,12)])])}const E=a(p,[["render",o]]);export{u as __pageData,E as default};
